// Some portions generated by Codex
package org.eclipse.rdf4j.federated.server;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NativeStoreServerCleanupTest {

	@Test
	void shutdownClosesRepositoriesReopenedByTests(@TempDir File directory) {
		NativeStoreServer server = new NativeStoreServer(directory);
		try {
			server.initialize(2);
			server.getRepository(1).init();
			server.getRepository(2).init();
			assertTrue(server.getRepository(1).isInitialized());
			assertTrue(server.getRepository(2).isInitialized());

			server.shutdown();

			assertFalse(server.getRepository(1).isInitialized());
			assertFalse(server.getRepository(2).isInitialized());
		} finally {
			server.shutdown();
		}
	}
}
